"use client"

import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import type { Recipient } from "../schema"

/** CAND-002 ListRow gap: leading initials + title/subtitle + trailing currency badge. */
export function RecipientRow({
  recipient,
  selected,
  onSelect,
}: {
  recipient: Recipient
  selected: boolean
  onSelect: () => void
}) {
  const initials = recipient.name
    .split(" ")
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase()

  return (
    <div
      role="button"
      tabIndex={0}
      aria-pressed={selected}
      onClick={onSelect}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault()
          onSelect()
        }
      }}
      style={{
        display: "flex",
        alignItems: "center",
        gap: "var(--atlas-spacing-3)",
        padding: "var(--atlas-spacing-3)",
        borderRadius: "var(--atlas-radius-lg)",
        border: `var(--atlas-border-width-1) solid ${
          selected ? "var(--atlas-primary)" : "var(--atlas-border)"
        }`,
        backgroundColor: selected ? "var(--atlas-primary-subtle)" : "var(--atlas-surface)",
        cursor: "pointer",
        minHeight: "var(--atlas-touch-comfortable)",
      }}
    >
      <div
        aria-hidden
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          inlineSize: "var(--atlas-spacing-10)",
          blockSize: "var(--atlas-spacing-10)",
          borderRadius: "var(--atlas-radius-full)",
          backgroundColor: "var(--atlas-background-muted)",
          color: "var(--atlas-foreground-muted)",
          fontSize: "var(--atlas-font-size-sm)",
          fontWeight: "var(--atlas-font-weight-semibold)",
          flexShrink: 0,
        }}
      >
        {initials}
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-0_5)", flex: 1, minInlineSize: 0 }}>
        <span style={{ fontSize: "var(--atlas-text-body)", fontWeight: "var(--atlas-font-weight-medium)", color: "var(--atlas-foreground)" }}>
          {recipient.name}
        </span>
        <span style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-muted)" }}>
          {recipient.accountMasked}
        </span>
      </div>
      <Badge variant="secondary" size="sm">
        {recipient.currency}
      </Badge>
    </div>
  )
}

