"use client"

import { useMemo, useState } from "react"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { RECENT_RECIPIENTS } from "../schema"
import type { SendMoneyStepProps } from "../schema"
import { RecipientRow } from "./_parts"

function SearchIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
      <circle cx="7" cy="7" r="5" stroke="currentColor" strokeWidth="1.5" />
      <path d="M11 11L14 14" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
    </svg>
  )
}

export function Recipient({ data, patch, next }: SendMoneyStepProps) {
  const [query, setQuery] = useState("")

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return RECENT_RECIPIENTS
    return RECENT_RECIPIENTS.filter((r) => r.name.toLowerCase().includes(q))
  }, [query])

  const select = (id: string) => {
    const recipient = RECENT_RECIPIENTS.find((r) => r.id === id)
    if (!recipient) return
    patch({
      recipientId: recipient.id,
      recipientName: recipient.name,
      recipientAccountMasked: recipient.accountMasked,
      recipientCurrency: recipient.currency,
    })
    next()
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-4)", paddingInline: "var(--atlas-spacing-4)" }}>
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
        <Label htmlFor="recipient-search" size="sm">
          Search recipients
        </Label>
        <Input
          id="recipient-search"
          variant="unstyled"
          size="md"
          placeholder="Search by name"
          leadingIcon={<SearchIcon />}
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          style={{
            border: `var(--atlas-border-width-1) solid var(--atlas-border)`,
            borderRadius: "var(--atlas-radius-lg)",
            paddingInline: "var(--atlas-spacing-3)",
          }}
        />
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        <span style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-muted)", fontWeight: "var(--atlas-font-weight-medium)" }}>
          Recent recipients
        </span>
        {filtered.length === 0 ? (
          <span style={{ fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }}>
            No recipients match &ldquo;{query}&rdquo;.
          </span>
        ) : (
          filtered.map((recipient) => (
            <RecipientRow
              key={recipient.id}
              recipient={recipient}
              selected={data.recipientId === recipient.id}
              onSelect={() => select(recipient.id)}
            />
          ))
        )}
      </div>
    </div>
  )
}

