"use client"

import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { RATES, SOURCE_CURRENCY, feeFor } from "../schema"
import type { SendMoneyStepProps } from "../schema"

function toNumber(value: string): number {
  const n = Number(value)
  return Number.isFinite(n) ? n : 0
}

export function Amount({ data, patch, next, back }: SendMoneyStepProps) {
  const rate = RATES[data.recipientCurrency] ?? 1
  const sendAmount = toNumber(data.sendAmount)
  const fee = feeFor(sendAmount)
  const total = sendAmount > 0 ? Math.round((sendAmount + fee) * 100) / 100 : 0
  const isValid = sendAmount > 0

  const onSendChange = (value: string) => {
    const amount = toNumber(value)
    patch({
      sendAmount: value,
      receiveAmount: amount > 0 ? (Math.round(amount * rate * 100) / 100).toString() : "",
    })
  }

  const onReceiveChange = (value: string) => {
    const amount = toNumber(value)
    patch({
      receiveAmount: value,
      sendAmount: amount > 0 ? (Math.round((amount / rate) * 100) / 100).toString() : "",
    })
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-4)", paddingInline: "var(--atlas-spacing-4)" }}>
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
        <Label htmlFor="you-send" size="sm">
          You send
        </Label>
        <Input
          id="you-send"
          size="md"
