import { FlowShell } from "../_shared/FlowShell"
import { useFlowState } from "../_shared/useFlowState"
import { SEND_MONEY_INITIAL, SEND_MONEY_STEPS, SendMoneyData } from "./schema"
import { Recipient } from "./steps/Recipient"
import { Amount } from "./steps/Amount"
import { Review } from "./steps/Review"

export default function SendMoneyFlowPage() {
  const flow = useFlowState<SendMoneyData>({
    totalSteps: SEND_MONEY_STEPS.length,
    initialData: SEND_MONEY_INITIAL,
  })
  const props = { data: flow.data, patch: flow.patch, next: flow.next, back: flow.back, goTo: flow.goTo }
  const key = SEND_MONEY_STEPS[flow.step]

  return (
    <FlowShell
      title="Send money"
      step={flow.step}
      totalSteps={SEND_MONEY_STEPS.length}
      onReset={flow.reset}
      phoneBackground="var(--atlas-background)"
    >
      {key === "recipient" && <Recipient {...props} />}
      {key === "amount" && <Amount {...props} />}
      {key === "review" && <Review {...props} />}
    </FlowShell>
  )
